  const f=this.fighters[id];
  if(!this.externalControl || !CATALOG[kind] || this.phase==='finished' || f.down || f.mode!=='upright' || !f.grip || f.motion || f.slashTime>0 || f.recovery>0 || f.recoilTime>0 || f.stamina<CATALOG[kind].cost) return false;
