  f.motion=createMotion(kind,f.motionPose??restPose(f.aim.toArray()),home,f.counterTime>0);
  f.stamina-=CATALOG[kind].cost;f.counterTime=0;
  f.slashDuration=duration(f.motion);f.windupDuration=f.motion.windup;f.slashTime=f.slashDuration;f.lowStrike=kind==='low_cut';return true;
}
